def generate_partition(N=40):
    S1 = {x for x in range(1, N + 1) if x % 4 == 1 or x % 4 == 2}
    S2 = {x for x in range(1, N + 1) if x % 4 == 3}
    S3 = {x for x in range(1, N + 1) if x % 4 == 0 and x <= 20}
    S4 = {x for x in range(1, N + 1) if x % 4 == 0 and x > 20}

    return S1, S2, S3, S4

def is_sum_free(S):
    # Check if there exist x, y in S such that x + y is also in S.
    # Since repetition is allowed, we check x+y for all x, y in S.
    S_list = list(S)
    for x in S_list:
        for y in S_list:
            if x + y in S:
                return False
    return True

S1, S2, S3, S4 = generate_partition()
sets = {
    "S1": S1,
    "S2": S2,
    "S3": S3,
    "S4": S4
}

results = {}
for name, S in sets.items():
    is_sf = is_sum_free(S)
    results[name] = is_sf
    print(f"--- {name} ---")
    print(f"Set size: {len(S)}")

    if not is_sf:
        # Find a counterexample
        counterexamples = []
        S_list = list(S)
        for x in S_list:
            for y in S_list:
                sum_xy = x + y
                if sum_xy in S:
                    counterexamples.append((x, y, sum_xy))
        print(f"FAILURE: Not sum-free. Counterexamples found: {counterexamples}")
    else:
        print("SUCCESS: Sum-free.")

def is_sum_free(s):
    """Checks if a set s is sum-free. (x+y is never in s for x, y in s)."""
    s_list = list(s)
    for i in range(len(s_list)):
        for j in range(len(s_list)):
            x = s_list[i]
            y = s_list[j]
            if x + y in s:
                return False
    return True

# Define the sets based on W3's modulo 4 construction
N = 40
S1 = {x for x in range(1, N + 1) if x % 4 == 1 or x % 4 == 2}
S2 = {x for x in range(1, N + 1) if x % 4 == 3}
S3 = {x for x in range(1, N + 1) if x % 4 == 0 and x <= 20}
S4 = {x for x in range(1, N + 1) if x % 4 == 0 and x > 20}

sets = [S1, S2, S3, S4]
results = {}

for i, S in enumerate(sets):
    is_sf = is_sum_free(S)
    results[f'S{i+1}'] = is_sf

for set_name, is_sf in results.items():
    print(f"{set_name}: Sum-free = {is_sf}")
